mapper.select:
SELECT
DISTINCT
ti.id, ti.code, ti.contact_address, ti.contact_mobile, ti.contact_name, ti.create_time, ti.creator_id,
ti.description, ti.intro, ti.name, ti.status, ti.tenant_type, ti.update_time, ti.updator_id
FROM uic_tenant_info ti
left join uic_tenant_member tm ON (ti.id = tm.tenant_id

)


        and tm.user_id = #{condition.loginStaffNo}


        AND ti.id = #{condition.tenantId}


        AND ti.name like concat('%',#{condition.name}, '%')


        AND ti.tenant_type = #{condition.tenantType}


ORDER BY id
